// Generated by OrchestKit Claude Plugin
// Created: 2026-08-30

/**
 * Sandbox posture: what CC's own Bash sandbox is configured to enforce.
 *
 * There is no runtime API for a hook to ask "is the sandbox on"; the only
 * signal is the settings files. This resolves `sandbox.*` across the four
 * scopes the way CC does (project local > project > user local > user) and
 * reports enabled / network policy. Guards read it per process (see
 * isSandboxNetworkEnforced for why not a SessionStart export).
 *
 * #3322 (operator decision 2026-08-23): freeze network-egress-guard and lean
 * on the sandbox. With a network policy enforced by the OS, the guard's ASK
 * tier (exfil-shaped uploads to non-allowlisted hosts) is a second, weaker
 * guesser in front of a real boundary, so it stands down; the DENY tier
 * (pipe-to-shell RCE shapes) is about executing fetched bytes, which no
 * network allowlist judges, so it stays.
 *
 * Managed settings and the `--settings` CLI flag can also enable the sandbox
 * and are not readable here; a session under either reads as "unknown" and
 * the guard keeps its full behaviour. Fail closed, never open.
 */
import { existsSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

export type SandboxEnabled = 'true' | 'false' | 'unknown';
export type SandboxNetwork = 'allowlist' | 'denylist' | 'none';

export interface SandboxPosture {
  enabled: SandboxEnabled;
  /** Which network policy the enabled sandbox carries, if any. */
  network: SandboxNetwork;
  /** The settings file the `enabled` answer came from, for doctor output. */
  source: string;
}

interface SandboxBlock {
  enabled?: unknown;
  network?: { allowedDomains?: unknown; deniedDomains?: unknown; strictAllowlist?: unknown };
}

function readSandboxBlock(file: string): SandboxBlock | null {
  try {
    if (!existsSync(file)) return null;
    const parsed = JSON.parse(readFileSync(file, 'utf8')) as { sandbox?: SandboxBlock };
    return parsed && typeof parsed.sandbox === 'object' && parsed.sandbox ? parsed.sandbox : null;
  } catch {
    return null; // silent: fail-open on an unreadable settings file, the answer becomes "unknown"
  }
}

/** Settings files in CC precedence order (first hit wins). */
export function settingsScopes(projectDir: string, home: string = homedir()): string[] {
  return [
    join(projectDir, '.claude', 'settings.local.json'),
    join(projectDir, '.claude', 'settings.json'),
    join(home, '.claude', 'settings.local.json'),
    join(home, '.claude', 'settings.json'),
  ];
}

export function resolveSandboxPosture(projectDir: string, home: string = homedir()): SandboxPosture {
  let enabled: SandboxEnabled = 'unknown';
  let source = '';
  let network: SandboxNetwork = 'none';
  for (const file of settingsScopes(projectDir, home)) {
    const block = readSandboxBlock(file);
    if (!block) continue;
    if (enabled === 'unknown' && typeof block.enabled === 'boolean') {
      enabled = block.enabled ? 'true' : 'false';
      source = file;
    }
    if (network === 'none' && block.network && typeof block.network === 'object') {
      const allowed = Array.isArray(block.network.allowedDomains) ? block.network.allowedDomains.length : 0;
      const denied = Array.isArray(block.network.deniedDomains) ? block.network.deniedDomains.length : 0;
      if (allowed > 0 || block.network.strictAllowlist === true) network = 'allowlist';
      else if (denied > 0) network = 'denylist';
    }
  }
  return { enabled, network, source };
}

/**
 * Guard-side read. ORK_SANDBOX_ENABLED / ORK_SANDBOX_NETWORK in the env are an
 * explicit override (tests, operators); otherwise the four settings scopes are
 * read here, in the hook process. Measured 2026-08-29 on 2.1.251: a SessionStart
 * hook's CLAUDE_ENV_FILE export never reached a later hook, so publishing the
 * posture once at session start is not a mechanism this can lean on. The read
 * is four existsSync calls and at most four small JSON parses, well inside the
 * PreToolUse budget, and it fails closed: unreadable or absent means "unknown",
 * and unknown keeps the guard's full behaviour.
 *
 * True only when the sandbox is on AND carries a network policy; an enabled
 * sandbox with no network block still lets every egress through.
 */
export function isSandboxNetworkEnforced(projectDir?: string, env: NodeJS.ProcessEnv = process.env, home: string = homedir()): boolean {
  const e = env.ORK_SANDBOX_ENABLED;
  const n = env.ORK_SANDBOX_NETWORK;
  if (e !== undefined || n !== undefined) {
    return e === 'true' && (n === 'allowlist' || n === 'denylist');
  }
  if (!projectDir) return false;
  const p = resolveSandboxPosture(projectDir, home);
  return p.enabled === 'true' && p.network !== 'none';
}
